// Prevents an extra console window on Windows in release builds.
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

//! The Unified Inbox desktop shell (ADR-3, ADR-8). A thin Tauri frame whose
//! one window loads the GUI from the relay origin pinned at configure time.
//! It adds what a browser cannot do for Reply (FR-13, FR-14): detecting
//! whether the native app for a deep link is installed and launching it.
//!
//! The two commands below are exposed to the relay origin only, through the
//! `remote-gui` capability generated by `bun run configure`.

use serde::Serialize;
use std::process::Command;
use tauri::webview::NewWindowResponse;
use tauri::{Manager, WebviewUrl, WebviewWindowBuilder};
use url::Url;

/// Which desktop the shell runs on. The GUI's deep-link resolver uses it to
/// disable iMessage Reply on Windows (FR-15).
#[tauri::command]
fn platform() -> &'static str {
    if cfg!(target_os = "macos") {
        "macos"
    } else if cfg!(target_os = "windows") {
        "windows"
    } else {
        "linux"
    }
}

#[derive(Serialize)]
struct Opened {
    opened: &'static str,
}

/// Opens the deepest link that can be honored on this machine: the native URL
/// when the app for its scheme is installed, else the web URL in the default
/// browser, else nothing. Returns which one was opened.
#[tauri::command]
fn open_deep_link(native: Option<String>, web: Option<String>) -> Opened {
    if let Some(native) = native.as_deref().filter(|s| !s.is_empty()) {
        if let Ok(url) = Url::parse(native) {
            if native_app_installed(url.scheme()) && tauri_plugin_opener::open_url(native, None::<&str>).is_ok() {
                return Opened { opened: "native" };
            }
        }
    }
    if let Some(web) = web.as_deref().filter(|s| !s.is_empty()) {
        if let Ok(url) = Url::parse(web) {
            if matches!(url.scheme(), "http" | "https") && tauri_plugin_opener::open_url(web, None::<&str>).is_ok() {
                return Opened { opened: "web" };
            }
        }
    }
    Opened { opened: "none" }
}

/// The application that owns each deep-link scheme, by its bundle name on
/// macOS. Schemes outside this table count as not installed, so the web URL
/// is used.
fn app_name_for_scheme(scheme: &str) -> Option<&'static str> {
    match scheme {
        "slack" => Some("Slack"),
        "whatsapp" => Some("WhatsApp"),
        "imessage" | "sms" => Some("Messages"),
        _ => None,
    }
}

#[cfg(target_os = "macos")]
fn native_app_installed(scheme: &str) -> bool {
    // `open -Ra <App>` exits 0 only when Launch Services knows the app.
    let Some(app) = app_name_for_scheme(scheme) else { return false };
    Command::new("/usr/bin/open")
        .args(["-Ra", app])
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

#[cfg(target_os = "windows")]
fn native_app_installed(scheme: &str) -> bool {
    // A registered URL protocol has a key under HKEY_CLASSES_ROOT\<scheme>.
    // The table limits the lookup to the schemes Reply uses.
    if app_name_for_scheme(scheme).is_none() {
        return false;
    }
    use std::os::windows::process::CommandExt;
    const CREATE_NO_WINDOW: u32 = 0x0800_0000;
    Command::new("reg")
        .args(["query", &format!("HKCR\\{scheme}"), "/ve"])
        .creation_flags(CREATE_NO_WINDOW)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

#[cfg(not(any(target_os = "macos", target_os = "windows")))]
fn native_app_installed(scheme: &str) -> bool {
    // The desktop's default handler for the scheme, if any.
    if app_name_for_scheme(scheme).is_none() {
        return false;
    }
    Command::new("xdg-mime")
        .args(["query", "default", &format!("x-scheme-handler/{scheme}")])
        .output()
        .map(|o| o.status.success() && !o.stdout.iter().all(|b| b.is_ascii_whitespace()))
        .unwrap_or(false)
}

/// Where the main window may navigate: the relay origin itself and Slack,
/// whose authorization round trip happens in this window (ADR-10). Anything
/// else opens in the default browser instead.
fn navigation_allowed(relay_origin: &str, url: &Url) -> bool {
    if url.origin().ascii_serialization() == relay_origin {
        return true;
    }
    if url.scheme() == "https" {
        if let Some(host) = url.host_str() {
            return host == "slack.com" || host.ends_with(".slack.com");
        }
    }
    false
}

fn main() {
    tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .invoke_handler(tauri::generate_handler![platform, open_deep_link])
        .setup(|app| {
            let window_config = app
                .config()
                .app
                .windows
                .iter()
                .find(|w| w.label == "main")
                .cloned()
                .expect("tauri.conf.json defines the main window; run `bun run configure`");
            let relay_origin = match &window_config.url {
                WebviewUrl::External(url) => url.origin().ascii_serialization(),
                other => panic!("the main window's url must be the relay origin, got {other:?}"),
            };
            let nav_origin = relay_origin.clone();
            let handle = app.handle().clone();
            WebviewWindowBuilder::from_config(app.handle(), &window_config)?
                .on_navigation(move |url| {
                    if navigation_allowed(&nav_origin, url) {
                        return true;
                    }
                    let _ = tauri_plugin_opener::open_url(url.as_str(), None::<&str>);
                    false
                })
                // window.open and target=_blank: the shell has one window, so a
                // link that may stay in it navigates the main window and
                // anything else goes to the default browser.
                .on_new_window(move |url, _features| {
                    if navigation_allowed(&relay_origin, &url) {
                        if let Some(main) = handle.get_webview_window("main") {
                            let _ = main.navigate(url);
                        }
                    } else {
                        let _ = tauri_plugin_opener::open_url(url.as_str(), None::<&str>);
                    }
                    NewWindowResponse::Deny
                })
                .build()?;
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("error while running the Unified Inbox shell");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn relay_and_slack_navigate_in_window() {
        let relay = "https://inbox.example.net";
        assert!(navigation_allowed(relay, &Url::parse("https://inbox.example.net/oauth/slack/callback?code=1").unwrap()));
        assert!(navigation_allowed(relay, &Url::parse("https://slack.com/oauth/v2/authorize?x=1").unwrap()));
        assert!(navigation_allowed(relay, &Url::parse("https://myteam.slack.com/").unwrap()));
        assert!(!navigation_allowed(relay, &Url::parse("https://evil.example.net/").unwrap()));
        assert!(!navigation_allowed(relay, &Url::parse("http://slack.com/").unwrap()));
        assert!(!navigation_allowed(relay, &Url::parse("https://notslack.com/").unwrap()));
        assert!(!navigation_allowed(relay, &Url::parse("https://inbox.example.net.evil/").unwrap()));
    }

    #[test]
    fn scheme_table() {
        assert_eq!(app_name_for_scheme("slack"), Some("Slack"));
        assert_eq!(app_name_for_scheme("whatsapp"), Some("WhatsApp"));
        assert_eq!(app_name_for_scheme("imessage"), Some("Messages"));
        assert_eq!(app_name_for_scheme("zoommtg"), None);
    }
}
